const data = JSON.parse($input.first().json.stdout);
const ALERT_THRESHOLD = 30;

const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const machines = Object.entries(data.machines).map(([id, m]) => ({
  machine_id: id,
  health_index: m.health_index,
  worst_defect: m.worst_defects && m.worst_defects[0] ? m.worst_defects[0].defect : null,
  defect_signals: m.defect_signals || {},
}));

machines.sort((a, b) => (a.health_index ?? 100) - (b.health_index ?? 100));

const warnings = machines.filter(m => m.health_index !== null && m.health_index < ALERT_THRESHOLD);

const summaryText = warnings.length
  ? `⚠️ 위험 장비 ${warnings.length}대: ` + warnings.map(w => `${w.machine_id}(${w.health_index})`).join(', ')
  : `현재 임계값(${ALERT_THRESHOLD}) 이하로 위험한 장비 없음`;

// 장비 전체 개요 표
const overviewRows = machines.map(m => `<tr>
  <td>${esc(m.machine_id)}</td>
  <td style="color:${m.health_index < ALERT_THRESHOLD ? '#d03b3b' : '#0ca30c'};font-weight:bold;">${m.health_index}</td>
  <td>${esc(m.worst_defect)}</td>
</tr>`).join('');

// 위험 장비만 defect/원인변수 상세
let detailHtml = '';
for (const m of warnings) {
  detailHtml += `<h3 style="margin-top:20px;">${esc(m.machine_id)} (Health Index ${m.health_index})</h3>`;
  const defectsSorted = Object.entries(m.defect_signals).sort((a, b) => (a[1].health_index ?? 100) - (b[1].health_index ?? 100));
  for (const [defect, sig] of defectsSorted) {
    if (sig.health_index === null || sig.health_index >= ALERT_THRESHOLD) continue;
    const occ = sig.actual_occurred_recent_7d ? ` — 최근 7일간 실제 ${sig.occurred_days_recent_7d}일 발생` : '';
    detailHtml += `<p style="margin:8px 0 4px;"><b>${esc(defect)}</b> (Health Index ${sig.health_index})${occ}</p>`;
    detailHtml += `<table border="1" cellpadding="5" cellspacing="0" style="border-collapse:collapse;font-size:12.5px;width:100%;">
      <tr style="background:#f2f2f2;"><th>원인변수</th><th>현재값</th><th>기준값</th><th>정상범위</th><th>스펙출처</th><th>여유(HI)</th><th>추세</th></tr>`;
    for (const [factorName, c] of Object.entries(sig.causes || {})) {
      const trend = c.early_warning_active ? '🔺 경보 활성' : (c.trend_direction || '-');
      const specTag = c.spec_source === 'mentor_spec' ? '실측 스펙' : '정상군 추정';
      detailHtml += `<tr>
        <td>${esc(factorName)}</td>
        <td>${c.current_value}</td>
        <td>${c.baseline_median}</td>
        <td>${c.lsl} ~ ${c.usl}</td>
        <td>${specTag}</td>
        <td>${c.health_index}</td>
        <td>${trend}</td>
      </tr>`;
    }
    detailHtml += `</table>`;
  }
}

const reportHtml = `<div style="font-family:sans-serif;max-width:640px;">
  <h2>SUGENT Health Index 리포트</h2>
  <p style="color:#666;font-size:13px;">생성 시각: ${esc(data.generated_at)}</p>
  <p style="font-size:15px;"><b>${esc(summaryText)}</b></p>
  <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px;">
    <tr style="background:#f2f2f2;"><th>장비</th><th>Health Index</th><th>최악 defect</th></tr>
    ${overviewRows}
  </table>
  ${detailHtml ? `<h3 style="margin-top:24px;">위험 상세</h3>${detailHtml}` : ''}
  <p style="color:#999;font-size:11px;margin-top:24px;">spec_source가 "정상군 추정"인 항목은 멘토 실측 스펙이 아니라 정상군 분포 기반 임시값입니다 — 참고용.</p>
</div>`;

return [{
  json: {
    generated_at: data.generated_at,
    alert_threshold: ALERT_THRESHOLD,
    summary: summaryText,
    report_html: reportHtml,
    has_warning: warnings.length > 0,
    warnings,
    machines: machines.map(({ defect_signals, ...rest }) => rest),
  },
}];
